import java.util.ArrayList;
import java.util.List;

/**
 * FitnessFunction.java
 *
 * Evaluates candidate execution orders generated by the QEA optimizer
 * against a given {@link SystemState}.
 *
 * Multi-objective fitness function (lower = better):
 *   Fitness = 1000 × DeadlockPenalty + 100 × UnfinishedProcesses + WaitingTime + ResourceWaste
 *
 * Components:
 *   1. DeadlockPenalty: 1.0 if any processes remain permanently blocked (deadlocked), 0.0 otherwise.
 *   2. UnfinishedProcesses: count of processes that could not finish due to deadlock or lack of resources.
 *   3. WaitingTime: total time steps processes spent queued/blocked before being granted resources.
 *   4. ResourceWaste: total idle resource instances at the end of the simulation.
 *
 * Hybrid Constraint Mode:
 *   When {@code useHybridConstraint == true}, Banker's Algorithm acts as a hard filter.
 *   If the state is unsafe or the candidate order causes deadlock, a penalty of
 *   {@code Double.MAX_VALUE / 2.0} is assigned, ensuring unsafe candidates never win.
 *
 * @author  OSDS-CP Group
 * @version 1.0  (Phase 1)
 */
public class FitnessFunction {

    public static final double DEADLOCK_WEIGHT   = 1000.0;
    public static final double UNFINISHED_WEIGHT = 100.0;
    public static final double WAIT_WEIGHT       = 1.0;
    public static final double WASTE_WEIGHT      = 1.0;

    private final boolean useHybridConstraint;

    /** Constructs a standard QEA fitness function (soft penalty for deadlocks). */
    public FitnessFunction() {
        this(false);
    }

    /**
     * Constructs a fitness function with optional hybrid Banker validation.
     *
     * @param useHybridConstraint true to enforce Banker's Algorithm as a hard constraint
     */
    public FitnessFunction(boolean useHybridConstraint) {
        this.useHybridConstraint = useHybridConstraint;
    }

    public boolean isHybrid() {
        return useHybridConstraint;
    }

    /**
     * Evaluates a candidate execution order on the specified system state.
     * Populates all evaluation metrics on the {@link CandidateSolution} object.
     *
     * @param sol   the candidate solution to evaluate
     * @param state the system state snapshot
     * @return the calculated fitness value (lower is better)
     */
    public double evaluate(CandidateSolution sol, SystemState state) {
        if (sol == null)   throw new IllegalArgumentException("sol must not be null");
        if (state == null) throw new IllegalArgumentException("state must not be null");

        final int n = state.getNumProcesses();
        final int m = state.getNumResources();

        // ── Fast check in Hybrid mode ─────────────────────────────────────────
        if (useHybridConstraint && !BankersAlgorithm.isSafe(state)) {
            sol.fitness            = Double.MAX_VALUE / 2.0;
            sol.isSafe             = false;
            sol.processesCompleted = 0;
            sol.totalWaitingTime   = n * 100.0;
            sol.resourceWaste      = state.getTotalResourceWaste();
            return sol.fitness;
        }

        // ── Discrete Execution Simulation ─────────────────────────────────────
        int[] work = state.getAvailableVector();
        boolean[] finished = new boolean[n];
        int completedCount = 0;
        double totalWaitingTime = 0.0;

        // Populate initial queue following candidate's specified order
        List<Integer> queue = new ArrayList<>(n);
        for (int pid : sol.order) {
            queue.add(pid);
        }

        // Multi-pass execution: process queue in order, re-evaluating blocked processes
        // until either all finish or no further progress can be made (deadlock)
        boolean progress = true;
        while (!queue.isEmpty() && progress) {
            progress = false;
            List<Integer> nextQueue = new ArrayList<>();

            for (int pid : queue) {
                if (canAllocate(state, pid, work, m)) {
                    // Process completes: release its held allocation back to Work
                    for (int j = 0; j < m; j++) {
                        work[j] += state.getAllocation(pid, j);
                    }
                    finished[pid] = true;
                    completedCount++;
                    progress = true;
                } else {
                    // Process is blocked: it waits during this scheduling cycle
                    totalWaitingTime += 1.0;
                    nextQueue.add(pid);
                }
            }

            queue = nextQueue;
        }

        // ── Compute Metrics ───────────────────────────────────────────────────
        int unfinished = n - completedCount;
        double deadlockPenalty = (unfinished > 0) ? 1.0 : 0.0;
        boolean safe = (unfinished == 0);

        // Resource waste = total available (idle) resources at end of run
        double resourceWaste = 0.0;
        for (int j = 0; j < m; j++) {
            resourceWaste += work[j];
        }

        sol.processesCompleted = completedCount;
        sol.totalWaitingTime   = totalWaitingTime;
        sol.resourceWaste      = resourceWaste;
        sol.isSafe             = safe;

        // ── Hard constraint enforcement for Hybrid QEA ────────────────────────
        if (useHybridConstraint && !safe) {
            sol.fitness = Double.MAX_VALUE / 2.0;
            return sol.fitness;
        }

        // ── Standard Multi-Objective Fitness ──────────────────────────────────
        double fitness = (DEADLOCK_WEIGHT * deadlockPenalty)
                       + (UNFINISHED_WEIGHT * unfinished)
                       + (WAIT_WEIGHT * totalWaitingTime)
                       + (WASTE_WEIGHT * resourceWaste);

        sol.fitness = fitness;
        return fitness;
    }

    /**
     * Helper to verify if process `pid`'s Need vector can be satisfied by current Work.
     */
    private boolean canAllocate(SystemState state, int pid, int[] work, int m) {
        for (int j = 0; j < m; j++) {
            if (state.getNeed(pid, j) > work[j]) {
                return false;
            }
        }
        return true;
    }
}
